\set ON_ERROR_STOP on
UPDATE "KnowledgeEntry" SET "revisionState"='SEALED',"sealManifestHash"='entry-seal',"sealPolicyVersion"='v1',"sealedAt"=clock_timestamp(),"sealedBy"='publisher',"updatedAt"=clock_timestamp() WHERE id='delivery-entry';
UPDATE "KnowledgePublication" SET state='SEALED',"sealedAt"=clock_timestamp(),"membershipClosedAt"=clock_timestamp() WHERE id='delivery-publication';

CREATE OR REPLACE FUNCTION public.p2b_force_commit_failure() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.detail->>'providerDeliveryId'='force-commit-failure' THEN RAISE EXCEPTION 'FORCED_COMMIT_FAILURE'; END IF;
 RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER p2b_force_commit_failure AFTER INSERT ON "KnowledgeAnswerOutcome" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.p2b_force_commit_failure();
